export const EARLY_TURN_POINT = Object.freeze([-42, 51.05, 15.82]);
export const EARLY_TURN_SEGMENT_INDEX = 2; // route vertex it turns short of

/**
 * ONE commissioned pre-capture correction (common-manual-runtime-commission.txt,
 * producer laterPreCaptureQualification 2026-09-06T16:22:33Z).
 *
 * A `walkTo(vertex, arrive 0.6)` can END 0.6 units SHORT of an original corner and
 * then turn: the body never crosses the signed incoming corner plane. That is a
 * navigation tolerance, not the signed proof. These predicates are the strict
 * form: at an intended-completed COMMON vertex the ACTUAL body must be observed
 * on the near side of the ORIGINAL incoming plane and then on the far side of it,
 * within the incoming segment's corridor, while supported.
 *
 * Nothing here relaxes anything: the plane is built from the frozen original
 * vertices, exact float coincidence is NOT required (a plane crossing is a sign
 * change, not a point hit), and the live credited `terraUnits` remains the
 * chapter's own proof. This never writes game state.
 */
/** Lateral distance from the corner at which a plane crossing still counts as THIS corner. */
export const PLANE_LATERAL_LIMIT_UNITS = 1.0;
/** Bound on how far past the plane a crossing pulse may leave the body (dry-passage safety). */
export const PLANE_MAX_OVERSHOOT_UNITS = 1.0;

/**
 * The ORIGINAL incoming plane at `route[index]`: the plane through that vertex whose
 * normal is the unit XZ direction of the incoming segment route[index-1] -> route[index].
 * Index 0 has no incoming segment and therefore has no plane.
 */
export function incomingPlaneAt(route, index) {
  if (!Array.isArray(route) || !Number.isInteger(index) || index <= 0 || index >= route.length) {
    return { ok: false, why: `no incoming segment at index ${index}`, index, point: null, normal: null };
  }
  const a = route[index - 1]; const b = route[index];
  const n = unit2([b[0] - a[0], b[2] - a[2]]);
  if (!n) return { ok: false, why: 'degenerate incoming segment', index, point: null, normal: null };
  return { ok: true, why: null, index, point: [b[0], b[1], b[2]], normal: n, from: [a[0], a[1], a[2]] };
}

/** Signed offset along the incoming direction: < 0 before the plane, >= 0 past it. */
export function signedPlaneOffset(p, plane) {
  if (!Array.isArray(p) || !plane?.ok) return null;
  return (p[0] - plane.point[0]) * plane.normal[0] + (p[2] - plane.point[2]) * plane.normal[1];
}

/** Distance from the corner measured IN the plane (how far off the corner the crossing was). */
export function planeLateralOffset(p, plane) {
  if (!Array.isArray(p) || !plane?.ok) return null;
  const dx = p[0] - plane.point[0]; const dz = p[2] - plane.point[2];
  return Math.abs(dx * -plane.normal[1] + dz * plane.normal[0]);
}

/**
 * Did the ACTUAL body physically cross this original incoming plane?
 *
 * Requires an observed sample strictly BEFORE the plane and a LATER observed sample
 * on or past it, the crossing sample within `lateralLimit` of the corner and
 * supported. Reaching a radius and turning away can never satisfy this.
 */
export function planeCrossingVerdict({
  samples = [], plane = null,
  lateralLimit = PLANE_LATERAL_LIMIT_UNITS,
  maxOvershoot = PLANE_MAX_OVERSHOOT_UNITS,
  requireSupported = true
} = {}) {
  if (!plane?.ok) return { crossed: false, why: `unusable plane: ${plane?.why ?? 'null'}`, before: null, cross: null };
  const seen = [];
  let before = null; let cross = null; let maxOffset = null;
  for (const s of samples) {
    const p = Array.isArray(s?.pose) ? s.pose : null;
    if (!p) continue;
    const offset = signedPlaneOffset(p, plane);
    const lateral = planeLateralOffset(p, plane);
    if (!Number.isFinite(offset)) continue;
    maxOffset = maxOffset === null ? offset : Math.max(maxOffset, offset);
    const rec = { ...s, offset, lateral };
    seen.push(rec);
    if (cross === null && offset < 0 && lateral <= lateralLimit) before = rec;
    if (cross === null && before !== null && offset >= 0) {
      if (lateral > lateralLimit) continue; // crossed the infinite plane somewhere else, not at THIS corner
      if (requireSupported && rec.supported !== true) continue;
      cross = rec;
    }
  }
  const overshootOk = cross === null ? null : (maxOffset ?? 0) <= maxOvershoot;
  return {
    crossed: cross !== null,
    why: cross !== null ? null
      : before === null ? `no observed sample strictly BEFORE the plane within ${lateralLimit}u of the corner`
        : 'body never reached the far side of the original incoming plane at this corner',
    before, cross, maxOffsetObserved: maxOffset, overshootWithinBound: overshootOk,
    samplesConsidered: seen.length, lateralLimit, maxOvershoot,
    plane: { index: plane.index, point: plane.point, normal: plane.normal }
  };
}

/**
 * The ordered credited frontier: crossings must have happened in ROUTE ORDER, in
 * time order, with the game's own credited units never going backwards across them.
 */
export function orderedFrontierVerdict({ crossings = [], expectedIndices = null, epsilon = 1e-6 } = {}) {
  const problems = [];
  if (!crossings.length) problems.push('no plane crossings were recorded');
  if (Array.isArray(expectedIndices)) {
    const got = crossings.map((c) => c.index);
    if (JSON.stringify(got) !== JSON.stringify(expectedIndices)) {
      problems.push(`crossed vertices ${JSON.stringify(got)} != required ordered set ${JSON.stringify(expectedIndices)}`);
    }
  }
  for (let i = 1; i < crossings.length; i += 1) {
    const a = crossings[i - 1]; const b = crossings[i];
    if (!(b.index > a.index)) problems.push(`vertex ${b.index} was not crossed after vertex ${a.index}`);
    if (!(b.atMs >= a.atMs)) problems.push(`vertex ${b.index} crossing precedes vertex ${a.index} in time`);
    if (Number.isFinite(a.units) && Number.isFinite(b.units) && b.units + epsilon < a.units) {
      problems.push(`credited units fell from ${a.units} to ${b.units} between vertices ${a.index} and ${b.index}`);
    }
  }
  for (const c of crossings) {
    if (c.crossed !== true) problems.push(`vertex ${c.index} is recorded without an actual crossing`);
    if (!Number.isFinite(c.units)) problems.push(`vertex ${c.index} crossing has no live credited units`);
  }
  return { ok: problems.length === 0, problems, crossings: crossings.map((c) => ({ index: c.index, atMs: c.atMs, units: c.units, offset: c.offset, lateral: c.lateral })) };
}

/**
 * The deviation's early turn must be a real EARLY turn: the actual body must still be
 * BEFORE the original z=16 plane. A body that overshot to 16+ is NOT the intended
 * deviation and must never be labelled as one.
 */
export function earlyTurnVerdict({ pose = null, plane = null, minShortfall = 0.02 } = {}) {
  const offset = signedPlaneOffset(pose, plane);
  if (offset === null || !Number.isFinite(offset)) {
    return { ok: false, offset: null, why: 'no measurable body offset against the original incoming plane' };
  }
  const ok = offset <= -minShortfall;
  return {
    ok, offset, shortfallUnits: -offset, minShortfall,
    why: ok ? null : `actual body is at offset ${offset.toFixed(3)} — it is NOT before the original plane, so this is an overshoot, not the intended early turn`
  };
}

// --- small vector helpers ---

