const ready = readJson(resolve(RUN_DIR, 'verification-ready.json'));
const control = readJson(resolve(RUN_DIR, 'verifier-control.json'));
const lockPath = arg('heavy-lock', process.env.PARAVOXIA_HEAVY_LOCK ?? null);
