  CG_POSES, CG_ROUTE_COMMON, CG_ROUTE_LONG, CG_COMMON_ROUTE_UNITS, EARLY_TURN_POINT,
  CG_F_CONTRACT, BODY_BODY_CLEARANCE_UNITS,
  bodyUsable, settled, directionsDistinct, chooseKey, unit2, distXZ, dist3, keyReceipt,
