  if (!gate('world-bound-and-noninitial-body', !!cg?.worldBound && bodyUsable(poseOf(cg) ?? []).ok, { worldBound: cg?.worldBound ?? 'unavailable', bodyPose: cg?.bodyPose ?? 'unavailable', bodyCentre: cg?.bodyCentre ?? 'unavailable' }))
